def s18_native_sp_states(graph):
 nodes,edges=graph[:2];states={0x7ff697aef420:0};pending=[0x7ff697aef420];conflicts=[];unknown=[];deltas={}
 while pending:
  ea=pending.pop();i=nodes[ea];m=i.get_canon_mnem().lower();delta=0;after=states[ea]
  rspdest=i.ops[0].type==ida_ua.o_reg and ida_idp.get_reg_name(i.ops[0].reg,8)=='rsp'
  if m=='push':delta=-8
  elif m=='pop':delta=8
  elif m in ('sub','add') and rspdest:
   if i.ops[1].type==ida_ua.o_imm:delta=(-1 if m=='sub' else 1)*i.ops[1].value
   elif ea in s18_sp_audit['probe_sizes']:delta=-s18_sp_audit['probe_sizes'][ea]
   else:unknown.append(hex(ea));continue
  elif m=='lea' and rspdest:
   assert ea==0x7ff697af4c5b and ida_bytes.get_bytes(ea,7).hex()=='488da5b8000000';delta=-64-states[ea]
  elif rspdest and i.get_canon_feature()&ida_idp.CF_CHG1:unknown.append(hex(ea));continue
  after+=delta
  if delta:deltas[ea+i.size]=delta
  for target in edges.get(ea,[]):
   if target not in states:states[target]=after;pending.append(target)
   elif states[target]!=after:conflicts.append((hex(target),states[target],after))
 return states,deltas,conflicts,unknown

